class Solution {
  public String entityParser(String text) {
    java.util.Map<String, String> entities = new java.util.HashMap<>();
    entities.put("&quot;", "\"");
    entities.put("&apos;", "'");
    entities.put("&amp;", "&");
    entities.put("&gt;", ">");
    entities.put("&lt;", "<");
    entities.put("&frasl;", "/");
    StringBuilder out = new StringBuilder();
    for (int i = 0; i < text.length(); ) {
      if (text.charAt(i) == '&') {
        int end = text.indexOf(';', i + 1);
        if (end != -1) {
          String entity = text.substring(i, end + 1);
          String replacement = entities.get(entity);
          if (replacement != null) {
            out.append(replacement);
            i = end + 1;
            continue;
          }
        }
      }
      out.append(text.charAt(i++));
    }
    return out.toString();
  }
}
